#!/usr/bin/env node
// port.mjs — generates the OpenCode, Hermes Agent and oh-my-pi (omp) files
// from the Claude Code sources under .claude/. The .claude/ tree stays the
// single source of truth; everything this writes is derived and carries a
// "generated" banner. Re-run after changing an agent, a rule, a skill's
// frontmatter, CLAUDE.md or .claude/settings.json.
//
// Usage:
//   node tools/ports/port.mjs            write the generated files
//   node tools/ports/port.mjs --check    exit 1 if any generated file is stale
//   node tools/ports/port.mjs hermes-snippet
//                                        print the ~/.hermes/config.yaml block
//                                        (Hermes loads hooks from the user
//                                        config only, never from a project)
//
// Node 18+, no dependencies. Reads only .claude/, CLAUDE.md and project files;
// writes only the paths listed in OUTPUTS below.

import { readFileSync, writeFileSync, mkdirSync, readdirSync, existsSync, rmSync, symlinkSync, lstatSync, readlinkSync } from "node:fs"
import { dirname, join, relative, basename } from "node:path"
import { fileURLToPath } from "node:url"

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..")
const BANNER_MD = "<!-- GENERATED by tools/ports/port.mjs from .claude/ — do not edit; edit the source and re-run. -->"
const BANNER_HASH = "# GENERATED by tools/ports/port.mjs from .claude/ — do not edit; edit the source and re-run."

// ---------------------------------------------------------------- frontmatter
// A YAML subset: `key: value`, `key: [a, b]`, `key:` + `  - item` lines.
// That is every shape .claude/ agents, skills and rules use.
function parseFrontmatter(text) {
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/)
  if (!m) return { fm: {}, body: text }
  const fm = {}
  let listKey = null
  for (const line of m[1].split(/\r?\n/)) {
    const item = line.match(/^\s+-\s+(.*)$/)
    if (item && listKey) { fm[listKey].push(unquote(item[1])); continue }
    const kv = line.match(/^([A-Za-z][\w-]*):\s*(.*)$/)
    if (!kv) continue
    const [, k, v] = kv
    if (v === "") { fm[k] = []; listKey = k; continue }
    listKey = null
    if (/^\[.*\]$/.test(v)) fm[k] = v.slice(1, -1).split(",").map(s => unquote(s.trim())).filter(Boolean)
    else fm[k] = unquote(v)
  }
  return { fm, body: text.slice(m[0].length) }
}
function unquote(s) {
  s = s.trim()
  if ((s.startsWith('"') && s.endsWith('"')) || (s.startsWith("'") && s.endsWith("'"))) return s.slice(1, -1)
  return s
}
const q = s => JSON.stringify(String(s)) // a YAML-safe double-quoted scalar
const csv = v => Array.isArray(v) ? v : String(v || "").split(",").map(s => s.trim()).filter(Boolean)

// ---------------------------------------------------------------- sources
const read = p => readFileSync(join(ROOT, p), "utf8")
const ls = (p, re) => existsSync(join(ROOT, p)) ? readdirSync(join(ROOT, p)).filter(f => re.test(f)).sort() : []

const agents = ls(".claude/agents", /\.md$/).map(f => {
  const { fm, body } = parseFrontmatter(read(`.claude/agents/${f}`))
  return { file: f, name: fm.name || basename(f, ".md"), fm, body }
})
const skills = ls(".claude/skills", /^[^.]/).filter(d => existsSync(join(ROOT, ".claude/skills", d, "SKILL.md"))).map(d => {
  const { fm, body } = parseFrontmatter(read(`.claude/skills/${d}/SKILL.md`))
  return { dir: d, name: fm.name || d, fm, body }
})
const rules = ls(".claude/rules", /\.md$/).map(f => {
  const { fm, body } = parseFrontmatter(read(`.claude/rules/${f}`))
  const title = (body.match(/^#\s+(.+)$/m) || [, basename(f, ".md")])[1].trim()
  return { file: f, name: basename(f, ".md"), paths: csv(fm.paths), title, body }
})
const settings = JSON.parse(read(".claude/settings.json"))

// ---------------------------------------------------------------- tool vocab
// Claude Code tool -> each host's tool. Used for the glossary, agent tool lists
// and agent permissions. null = the host has no such tool.
const TOOLS = {
  Read:      { opencode: "read",      hermes: "read_file",     omp: ["read"] },
  Write:     { opencode: "write",     hermes: "write_file",    omp: ["write"] },
  Edit:      { opencode: "edit",      hermes: "patch",         omp: ["edit"] },
  Glob:      { opencode: "glob",      hermes: "search_files",  omp: ["glob", "find"] },
  Grep:      { opencode: "grep",      hermes: "search_files",  omp: ["grep", "ast_grep"] },
  Bash:      { opencode: "shell",     hermes: "terminal",      omp: ["bash"] },
  WebSearch: { opencode: "websearch", hermes: "web_search",    omp: ["web_search"] },
  WebFetch:  { opencode: "webfetch",  hermes: "web_extract",   omp: ["read"] },
  Agent:     { opencode: "subagent",  hermes: "delegate_task", omp: ["task"] },
}
// Claude `model:` -> omp model role. OpenCode and Hermes take a concrete
// provider/model id, which this repo cannot know, so their agents inherit.
const OMP_MODEL = { opus: "@slow", haiku: "@smol" }

// ---------------------------------------------------------------- outputs
const out = new Map() // repo-relative path -> content
const emit = (p, s) => out.set(p, s.endsWith("\n") ? s : s + "\n")

// ---- shared: hooks.json (what the hook adapters run) ----------------------
const HOOK_SCRIPT = /\.claude\/hooks\/([\w.-]+\.sh)/
const hooks = {}
for (const [event, groups] of Object.entries(settings.hooks || {})) {
  hooks[event] = groups.map(g => ({
    matcher: g.matcher || "",
    hooks: g.hooks.map(h => {
      const m = String(h.command).match(HOOK_SCRIPT)
      return m && { script: `.claude/hooks/${m[1]}`, timeout: h.timeout || 60, async: !!h.async }
    }).filter(Boolean),
  }))
}
const perms = settings.permissions || {}
const toolPattern = s => { const m = String(s).match(/^(\w+)\((.*)\)$/); return m ? { tool: m[1], pattern: m[2] } : null }
const allow = (perms.allow || []).map(toolPattern).filter(Boolean)
const deny = (perms.deny || []).map(toolPattern).filter(Boolean)
emit("tools/ports/hooks.json", JSON.stringify({
  _generated: "tools/ports/port.mjs from .claude/settings.json — do not edit",
  hooks,
  permissions: { allow, deny },
}, null, 2))

// ---- shared: AGENTS.md -----------------------------------------------------
// CLAUDE.md with its @imports inlined (OpenCode and Hermes do not expand them)
// plus a host appendix. Claude Code keeps reading CLAUDE.md.
function inlineImports(text) {
  return text.replace(/^@(\S+)\s*$/gm, (_, p) => {
    if (!existsSync(join(ROOT, p))) return `@${p}`
    return `<!-- inlined from ${p} -->\n${read(p).replace(/^#\s/m, "### ")}`
  })
}
const ruleRows = rules.filter(r => r.paths.length).map(r =>
  `| ${r.paths.map(p => "`" + p + "`").join("<br>")} | [.claude/rules/${r.file}](.claude/rules/${r.file}) |`).join("\n")
const glossaryRows = [
  ["Read / Write / Edit", "read / write / edit", "read_file / write_file / patch", "read / write / edit"],
  ["Glob / Grep", "glob / grep", "search_files", "glob, find / grep"],
  ["Bash", "shell", "terminal", "bash"],
  ["AskUserQuestion", "question", "clarify", "ask"],
  ["Agent / Task (`subagent_type: X`)", "subagent, agent `X`", "delegate_task (see below)", "task, agent `X`"],
  ["Skill / typing `/name`", "skill tool / `/name`", "skill_view / `/name`", "read `skill://name` / `/skill:name`"],
  ["WebSearch / WebFetch", "websearch / webfetch", "web_search / web_extract", "web_search / read the URL"],
  ["TodoWrite", "todowrite", "todo", "todo"],
].map(r => `| ${r.join(" | ")} |`).join("\n")

emit("AGENTS.md", `${BANNER_MD}

${inlineImports(read("CLAUDE.md")).trim()}

## Running this studio outside Claude Code

This file is CLAUDE.md for OpenCode, Hermes Agent and oh-my-pi (omp). Claude
Code reads CLAUDE.md; everything else here is generated from it. The skills
and agents under \`.claude/\` name Claude Code's tools, so translate:

| Claude Code | OpenCode | Hermes Agent | omp |
|---|---|---|---|
${glossaryRows}

**Skills that start with a \`!\` line.** Many skills open with a line like
\`!\\\`bash "\${CLAUDE_SKILL_DIR}/../../hooks/yaml-helper.sh" resolve_config --keys …\\\`\`.
Claude Code runs that command before the skill is read; other hosts do not.
When you load such a skill, run the command yourself first, with
\`\${CLAUDE_SKILL_DIR}\` replaced by the skill's folder
(\`.claude/skills/<name>\`), and treat its output as the block the skill calls
"Resolved above". (OpenCode's \`/name\` commands already run it for you.)
\`$ARGUMENTS\` in a skill is the text typed after the command.

**Asking the user.** Every "AskUserQuestion" in a skill means your host's
ask tool from the table. If there is none, ask in plain text and wait — never
pick an answer for the user.

**Subagents.** The agents in \`.claude/agents/\` have generated twins with the
same names on OpenCode (\`.opencode/agents/\`) and omp (\`.omp/agents/\`).
Hermes has no named agents: call \`delegate_task\` with the agent's prompt —
the body of \`.claude/agents/<name>.md\` after its frontmatter — at the top of
\`context\`, and the task as \`goal\`.

**Path rules.** Before you create or edit a file whose path matches the left
column, read the rule file on the right and follow it. (omp loads these as
rules by itself.)

| Paths | Rule |
|---|---|
${ruleRows}

**Checks.** The hooks in \`.claude/hooks/\` (write, read, commit and push
guards; session start) run through \`.opencode/plugins/claude-studio.ts\` and
\`.omp/extensions/claude-studio.ts\`. Hermes runs them only after the user adds
the block that \`node tools/ports/port.mjs hermes-snippet\` prints to
\`~/.hermes/config.yaml\`. See [tools/ports/README.md](tools/ports/README.md).
`)

// ---- OpenCode ---------------------------------------------------------------
// Permissions: Claude Code's default mode asks before edits and unlisted
// commands. OpenCode evaluates the last matching rule, so: ask, then allow,
// then deny.
const ocPerm = (action, resource, effect) => ({ action, resource, effect })
const ocGlob = p => p.replace(/^\*\*\//, "*") // OpenCode `*` already crosses `/`
const ocPerms = [ocPerm("edit", "*", "ask"), ocPerm("shell", "*", "ask")]
for (const a of allow) if (a.tool === "Bash") ocPerms.push(ocPerm("shell", a.pattern, "allow"))
for (const d of deny) {
  if (d.tool === "Bash") ocPerms.push(ocPerm("shell", d.pattern, "deny"))
  else if (d.tool === "Read") ocPerms.push(ocPerm("read", ocGlob(d.pattern), "deny"))
  else if (d.tool === "Edit") ocPerms.push(ocPerm("edit", ocGlob(d.pattern), "deny"))
}
emit("opencode.json", JSON.stringify({
  $schema: "https://opencode.ai/config.json",
  _generated: "tools/ports/port.mjs from .claude/settings.json — do not edit",
  permissions: ocPerms,
}, null, 2))

const hostNote = host => {
  const name = { opencode: "OpenCode", omp: "oh-my-pi" }[host]
  const pick = t => [].concat(TOOLS[t][host])[0]
  return `> **Host: ${name}.** This prompt was written for Claude Code. Its tool
> names map as: Read→${pick("Read")}, Write→${pick("Write")}, Edit→${pick("Edit")}, Glob→${pick("Glob")},
> Grep→${pick("Grep")}, Bash→${pick("Bash")}, WebSearch→${pick("WebSearch")}, Agent/Task→${pick("Agent")}.
> As a subagent you cannot ask the user: return your questions to the caller.`
}
const memoryNote = a => a.fm.memory
  ? `\n\n> **Memory.** Your notes live in \`.claude/agent-memory/${a.name}/MEMORY.md\`. Read it
> first if it exists; record durable lessons there (see .claude/rules/agent-memory.md).`
  : ""
const skillsNote = (a, how) => a.fm.skills && a.fm.skills.length
  ? `\n\n> **Preloaded skills.** Before starting, load: ${a.fm.skills.map(s => "`" + s + "`").join(", ")} (${how}).`
  : ""

for (const a of agents) {
  const tools = new Set(csv(a.fm.tools))
  for (const t of csv(a.fm.disallowedTools)) tools.delete(t)
  const p = []
  if (!tools.has("Bash")) p.push(ocPerm("shell", "*", "deny"))
  if (!tools.has("Write") && !tools.has("Edit")) p.push(ocPerm("edit", "*", "deny"))
  if (!tools.has("WebSearch")) p.push(ocPerm("websearch", "*", "deny"), ocPerm("webfetch", "*", "deny"))
  if (!tools.has("Agent")) p.push(ocPerm("subagent", "*", "deny"))
  const fm = [
    "---",
    `description: ${q(a.fm.description || a.name)}`,
    "mode: subagent",
    a.fm.maxTurns ? `steps: ${Number(a.fm.maxTurns)}` : null,
    p.length ? "permissions:\n" + p.map(r => `  - { action: ${r.action}, resource: ${q(r.resource)}, effect: ${r.effect} }`).join("\n") : null,
    "---",
  ].filter(Boolean).join("\n")
  emit(`.opencode/agents/${a.name}.md`, `${fm}\n${BANNER_MD}\n\n${hostNote("opencode")}${memoryNote(a)}${skillsNote(a, "skill tool")}\n\n${a.body.trim()}`)
}

// Commands: one per user-invocable skill, so `/brainstorm` works. A skill's
// `!` lines run here as OpenCode command shell injection.
for (const s of skills) {
  if (String(s.fm["user-invocable"]) === "false") continue
  const bang = s.body.split(/\r?\n/).filter(l => /^!`.*`\s*$/.test(l))
    .map(l => l.replaceAll("${CLAUDE_SKILL_DIR}", `.claude/skills/${s.dir}`))
  const fm = ["---", `description: ${q(s.fm.description || s.name)}`, "---"].join("\n")
  emit(`.opencode/commands/${s.name}.md`, `${fm}
${BANNER_MD}
${bang.length ? "\n" + bang.join("\n") + "\n\nThe output above is the block the skill calls \"Resolved above\"; do not run the skill's own `!` line again.\n" : ""}
Load the \`${s.dir}\` skill with the skill tool and follow it.

Arguments: $ARGUMENTS`)
}

// ---- omp ---------------------------------------------------------------------
const yamlList = (k, xs) => `${k}:\n` + xs.map(x => `  - ${q(x)}`).join("\n")
const allNames = agents.map(a => a.name)
for (const a of agents) {
  const tools = new Set(csv(a.fm.tools))
  for (const t of csv(a.fm.disallowedTools)) tools.delete(t)
  const ompTools = [...new Set([...tools].flatMap(t => TOOLS[t] ? TOOLS[t].omp : []))]
  const fm = [
    "---",
    `name: ${q(a.name)}`,
    `description: ${q(a.fm.description || a.name)}`,
    yamlList("tools", ompTools),
    tools.has("Agent") ? yamlList("spawns", allNames.filter(n => n !== a.name)) : null,
    OMP_MODEL[a.fm.model] ? yamlList("model", [OMP_MODEL[a.fm.model]]) : null,
    a.fm.skills && a.fm.skills.length ? yamlList("autoloadSkills", a.fm.skills) : null,
    "---",
  ].filter(Boolean).join("\n")
  emit(`.omp/agents/${a.name}.md`, `${fm}\n${BANNER_MD}\n\n${hostNote("omp")}${memoryNote(a)}\n\n${a.body.trim()}`)
}
for (const r of rules) {
  const fm = ["---", `description: ${q(r.title)}`, r.paths.length ? yamlList("globs", r.paths) : "alwaysApply: true", "---"].join("\n")
  emit(`.omp/rules/${r.name}.md`, `${fm}\n${BANNER_MD}\n\n${r.body.trim()}`)
}
// omp: ask before writes (Claude Code's default mode), the settings.json
// command rules as bash patterns (first match wins: deny before allow), and
// no OpenCode commands — omp has /skill:<name> natively.
const ompPatterns = [
  ...deny.filter(d => d.tool === "Bash").map(d => ({ match: d.pattern, approval: "deny" })),
  ...allow.filter(a => a.tool === "Bash").map(a => ({ match: a.pattern, approval: "allow" })),
]
emit(".omp/config.yml", `${BANNER_HASH}
tools:
  approvalMode: write
commands:
  enableOpencodeProject: false
bash:
  patterns:
${ompPatterns.map(p => `    - match: ${q(p.match)}\n      approval: ${p.approval}`).join("\n")}`)

// ---------------------------------------------------------------- hermes
// Hermes reads project skills from .hermes/skills (after `hermes skills trust`).
// A symlink keeps one copy; see README for hosts without symlinks.
const HERMES_LINK = ".hermes/skills"

function hermesSnippet() {
  const py = `python3 ${join(ROOT, "tools/ports/hermes-hook.py")}`
  return `# Claude Code Game Studios checks for Hermes Agent (${ROOT}).
# Paste under the top level of ~/.hermes/config.yaml. The hook script does
# nothing outside a studio project, so it is safe in other repos.
hooks:
  pre_tool_call:
    - matcher: "terminal|write_file|patch|read_file"
      command: "${py} pre_tool_call"
      timeout: 30
  post_tool_call:
    - matcher: "write_file|patch"
      command: "${py} post_tool_call"
      timeout: 15
  pre_llm_call:
    - command: "${py} pre_llm_call"
      timeout: 25
  on_session_end:
    - command: "${py} on_session_end"
      timeout: 10
# Skills load from the repo's .hermes/skills symlink after
# \`hermes skills trust\`. On a checkout without symlinks (Windows without
# developer mode), uncomment this instead:
# skills:
#   external_dirs:
#     - "${join(ROOT, ".claude/skills")}"
`
}

// ---------------------------------------------------------------- write/check
const generatedDirs = [".opencode/agents", ".opencode/commands", ".omp/agents", ".omp/rules"]
function plan() {
  // stale generated files in owned dirs are deleted
  const stale = []
  for (const d of generatedDirs) for (const f of ls(d, /\.md$/)) if (!out.has(`${d}/${f}`)) stale.push(`${d}/${f}`)
  return stale
}

const mode = process.argv[2]
if (mode === "hermes-snippet") { process.stdout.write(hermesSnippet()); process.exit(0) }
if (mode === "--check") {
  const bad = []
  for (const [p, s] of out) if (!existsSync(join(ROOT, p)) || read(p) !== s) bad.push(p)
  bad.push(...plan().map(p => `${p} (stale)`))
  let link = null
  try { link = readlinkSync(join(ROOT, HERMES_LINK)) } catch {}
  if (link !== "../.claude/skills") bad.push(`${HERMES_LINK} (symlink)`)
  if (bad.length) { console.error("port: out of date — run node tools/ports/port.mjs\n  " + bad.join("\n  ")); process.exit(1) }
  console.log(`port: ${out.size} generated files up to date`)
  process.exit(0)
}
if (mode) { console.error(`port: unknown argument ${mode}`); process.exit(2) }

for (const p of plan()) rmSync(join(ROOT, p))
for (const [p, s] of out) { mkdirSync(dirname(join(ROOT, p)), { recursive: true }); writeFileSync(join(ROOT, p), s) }
mkdirSync(join(ROOT, ".hermes"), { recursive: true })
try { lstatSync(join(ROOT, HERMES_LINK)) } catch { symlinkSync("../.claude/skills", join(ROOT, HERMES_LINK), "dir") }
console.log(`port: wrote ${out.size} files (${agents.length} agents, ${skills.length} skills, ${rules.length} rules)`)
